import tomli

def run_git(args, path='.'):
    result = subprocess.run(['git', '-C', path] + args, capture_output=True, text=True)
    if result.returncode != 0:
        return None
    return result.stdout

class GitGraph:
    def __init__(self, path='.', model_name='git-flow'):
        self.path = path
        self.repo_root = self.find_repo_root(path)
        self.model_name = self.load_model_name(model_name)
        self.persistence_rules = self.get_persistence_rules(self.model_name)

    def find_repo_root(self, path):
        curr = os.path.abspath(path)
        while curr != '/':
            if os.path.isdir(os.path.join(curr, '.git')):
                return curr
            curr = os.path.dirname(curr)
        return None

    def load_model_name(self, default_model):
        if not self.repo_root:
            return default_model
        config_path = os.path.join(self.repo_root, '.git', 'git-graph.toml')
        if os.path.exists(config_path):
            try:
                with open(config_path, 'rb') as f:
                    config = tomli.load(f)
                    return config.get('model', default_model)
            except:
                pass
        return default_model

    def get_persistence_rules(self, model_name):
        if model_name == 'git-flow':
            return [
                r'^(master|main|trunk)$',
                r'^(develop|dev)$',
                r'^feature.*$',
                r'^release.*$',
                r'^(bugfix|hotfix).*$',
                r'^tags/.*$'
            ]
        elif model_name == 'simple':
            return [
                r'^(master|main|trunk)$'
            ]
        else: # none
            return []

    def get_commits(self, max_count=None):
        args = ['log', '--all', '--format=%H %P|%D|%s|%at', '--topo-order']
        if max_count:
            args += ['-n', str(max_count)]
        output = run_git(args, self.path)
        if not output: return []

        commits = []
        for line in output.strip().split('\n'):
            if not line: continue
            parts = line.split('|')
            hp = parts[0].split()
            h = hp[0]
            ps = hp[1:]
            rs = parts[1]
            subj = parts[2]
            ts = int(parts[3])
            commits.append({
                'hash': h,
                'parents': ps,
                'refs': rs,
                'subject': subj,
                'timestamp': ts,
                'branch': None
            })
        return commits

    def identify_branches(self, commits):
        branches = {}
        for c in commits:
            if c['refs']:
                refs = [r.strip() for r in c['refs'].split(',')]
                for r in refs:
                    name = r
                    if ' -> ' in r:
                        name = r.split(' -> ')[1]
                    if name.startswith('tag: '):
                        name = 'tags/' + name[5:]
                    if name not in branches:
                        branches[name] = c['hash']
        for c in commits:
            match = re.search(r"Merge (?:branch|tag) '([^']+)'", c['subject'])
            if match:
                name = match.group(1)
                if name not in branches and len(c['parents']) > 1:
                    branches[name] = c['parents'][1]
        return branches

    def get_persistence(self, branch_name):
        for i, rule in enumerate(self.persistence_rules):
            if re.match(rule, branch_name):
                return i
        return 100

    def assign_commits(self, commits, branches):
        commit_map = {c['hash']: c for c in commits}
        sorted_branches = sorted(branches.items(), key=lambda x: (self.get_persistence(x[0]), x[0]))
        assigned_hashes = set()
        branch_assignments = []
        for name, head_hash in sorted_branches:
            if head_hash not in commit_map or head_hash in assigned_hashes:
                continue
            curr_hash = head_hash
            branch_commits = []
            while curr_hash in commit_map and curr_hash not in assigned_hashes:
                commit_map[curr_hash]['branch'] = name
                branch_commits.append(curr_hash)
                assigned_hashes.add(curr_hash)
                if not commit_map[curr_hash]['parents']:
                    break
                curr_hash = commit_map[curr_hash]['parents'][0]
            if branch_commits:
                branch_assignments.append({'name': name, 'commits': branch_commits})
        return branch_assignments

    def order_commits(self, commits, branch_assignments):
        child_counts = {c['hash']: 0 for c in commits}
        parents_map = {c['hash']: c['parents'] for c in commits}
        commit_map = {c['hash']: c for c in commits}
        for c in commits:
            for p in c['parents']:
                if p in child_counts:
                    child_counts[p] += 1
        branch_persistence = {a['name']: self.get_persistence(a['name']) for a in branch_assignments}
        def get_priority(h):
            c = commit_map[h]
            prio = branch_persistence.get(c['branch'], 100)
            return (prio, c['timestamp'])
        available = [c['hash'] for c in commits if child_counts[c['hash']] == 0]
        ordered_hashes = []
        while available:
            available.sort(key=get_priority, reverse=True)
            curr_hash = available.pop(0)
            ordered_hashes.append(curr_hash)
            for p in parents_map[curr_hash]:
                if p in child_counts:
                    child_counts[p] -= 1
                    if child_counts[p] == 0:
                        available.append(p)
        return [commit_map[h] for h in ordered_hashes]

    def assign_columns(self, ordered_commits, branch_assignments):
        hash_to_index = {c['hash']: i for i, c in enumerate(ordered_commits)}
        branch_info = {}
        for a in branch_assignments:
            name = a['name']
            indices = [hash_to_index[h] for h in a['commits']]
            start_idx = min(indices)
            end_idx = max(indices)
            last_commit = next(c for c in ordered_commits if c['hash'] == a['commits'][-1])
            if last_commit['parents']:
                p_idx = hash_to_index.get(last_commit['parents'][0])
                if p_idx is not None: end_idx = max(end_idx, p_idx)
            branch_info[name] = {'start': start_idx, 'end': end_idx}

        sorted_branch_names = [a['name'] for a in branch_assignments]
        sorted_branch_names.sort(key=lambda n: (self.get_persistence(n), n))

        columns = {}
        occupied = []
        for name in sorted_branch_names:
            info = branch_info[name]
            lifespan = set(range(info['start'], info['end'] + 1))
            assigned = False
            for i, occ in enumerate(occupied):
                if not (occ & lifespan):
                    occ.update(lifespan)
                    columns[name] = i
                    assigned = True
                    break
            if not assigned:
                columns[name] = len(occupied)
                occupied.append(lifespan)
        return columns

if __name__ == "__main__":
    gg = GitGraph()
    commits = gg.get_commits()
    branches = gg.identify_branches(commits)
    assignments = gg.assign_commits(commits, branches)
    ordered = gg.order_commits(commits, assignments)
    columns = gg.assign_columns(ordered, assignments)
    for c in ordered:
        print(f"{c['hash'][:7]} (col {columns.get(c['branch'])}) {c['branch']}")
