            if os.path.isdir(os.path.join(curr, '.git')):
                return curr
            curr = os.path.dirname(curr)
        return None

    def should_use_color(self, color_opt):
        if color_opt == 'always': return True
        if color_opt == 'never': return False
        return sys.stdout.isatty()

