{"command":"cat <<'EOF' > main.py
import sys
import os
import re
import subprocess
import argparse
try:
    import tomli
except ImportError:
    tomli = None

def run_git(args, path='.'):
    result = subprocess.run(['git', '-C', path] + args, capture_output=True, text=True)
    if result.returncode != 0: return None
    return result.stdout

class GitGraph:
    def __init__(self, path='.', model_name='git-flow', style='normal', color='auto'):
        self.path = path
        self.repo_root = self.find_repo_root(path)
        self.model_name = self.load_model_name(model_name)
        self.style = style
        self.color = self.should_use_color(color)
        self.persistence_rules = self.get_persistence_rules(self.model_name)
        self.terminal_colors = [
            (r'^(master|main|trunk)$', ['bright_blue']),
            (r'^(develop|dev)$', ['bright_yellow']),
            (r'^(feature|fork/).*$', ['bright_magenta', 'bright_cyan']),
            (r'^release.*$', ['bright_green']),
            (r'^(bugfix|hotfix).*$', ['bright_red']),
            (r'^tags/.*$', ['bright_green']),
        ]

    def find_repo_root(self, path):
        curr = os.path.abspath(path)
        while curr != '/':
            if os.path.isdir(os.path.join(curr, '.git')): return curr
            curr = os.path.dirname(curr)
        return None

    def should_use_color(self, color_opt):
        if color_opt == 'always': return True
        if color_opt == 'never': return False
        return sys.stdout.isatty()

    def load_model_name(self, default_model):
        if not self.repo_root: return default_model
        config_path = os.path.join(self.repo_root, '.git', 'git-graph.toml')
        if os.path.exists(config_path) and tomli:
            try:
                with open(config_path, 'rb') as f:
                    config = tomli.load(f)
                    return config.get('model', default_model)
            except: pass
        return default_model

    def get_persistence_rules(self, model_name):
        if model_name == 'git-flow':
            return [r'^(master|main|trunk)$', r'^(develop|dev)$', r'^feature.*$', r'^release.*$', r'^(bugfix|hotfix).*$', r'^tags/.*$']
        elif model_name == 'simple':
            return [r'^(master|main|trunk)$']
        return []

    def get_color(self, branch_name, index=0):
        if not self.color: return ""
        color_name = 'white'
        for rule, colors in self.terminal_colors:
            if re.match(rule, branch_name):
                color_name = colors[index % len(colors)]
                break
        ansi = {'bright_blue': '\033[94m', 'bright_yellow': '\033[93m', 'bright_magenta': '\033[95m', 'bright_cyan': '\033[96m', 'bright_green': '\033[92m', 'bright_red': '\033[91m', 'white': '\033[97m', 'reset': '\033[0m'}
        return ansi.get(color_name, ansi['white'])

    def reset_color(self): return '\033[0m' if self.color else ""

    def get_commits(self, max_count=None):
        args = ['log', '--all', '--format=%H %P|%D|%s|%at', '--topo-order']
        if max_count: args += ['-n', str(max_count)]
        output = run_git(args, self.path)
        if not output: return []
        commits = []
        for line in output.strip().split('\n'):
            parts = line.split('|')
            hp = parts[0].split()
            commits.append({'hash': hp[0], 'parents': hp[1:], 'refs': parts[1], 'subject': parts[2], 'timestamp': int(parts[3]), 'branch': None})
        return commits

    def identify_branches(self, commits):
        branches = {}
        for c in commits:
            if c['refs']:
                for r in [ref.strip() for ref in c['refs'].split(',')]:
                    name = r.split(' -> ')[1] if ' -> ' in r else r
                    if name.startswith('tag: '): name = 'tags/' + name[5:]
                    if name not in branches: branches[name] = c['hash']
        for c in commits:
            match = re.search(r"Merge (?:branch|tag) '([^']+)'", c['subject'])
            if match:
                name = match.group(1)
                if name not in branches and len(c['parents']) > 1: branches[name] = c['parents'][1]
        return branches

    def get_persistence(self, branch_name):
        for i, rule in enumerate(self.persistence_rules):
            if re.match(rule, branch_name): return i
        return 100

    def assign_commits(self, commits, branches):
        commit_map = {c['hash']: c for c in commits}
        sorted_branches = sorted(branches.items(), key=lambda x: (self.get_persistence(x[0]), x[0]))
        assigned_hashes = set()
        assignments = []
