import sys
import os
import re
import subprocess
import argparse

def run_git(args, path='.'):
    result = subprocess.run(['git', '-C', path] + args, capture_output=True, text=True)
    if result.returncode != 0: return None
    return result.stdout

class GitGraph:
    def __init__(self, path='.', model_name='git-flow', style='normal', color='auto'):
        self.path = path
        self.repo_root = self.find_repo_root(path)
        self.model_name = self.load_model_name(model_name)
        self.style = style
        self.color = self.should_use_color(color)
        self.persistence_rules = self.get_persistence_rules(self.model_name)
        self.terminal_colors = [(r'^(master|main|trunk)$', ['bright_blue']), (r'^(develop|dev)$', ['bright_yellow']), (r'^(feature|fork/).*$', ['bright_magenta', 'bright_cyan']), (r'^release.*$', ['bright_green']), (r'^(bugfix|hotfix).*$', ['bright_red']), (r'^tags/.*$', ['bright_green'])]

    def find_repo_root(self, path):
        curr = os.path.abspath(path)
        while curr != '/':
            if os.path.isdir(os.path.join(curr, '.git')): return curr
            curr = os.path.dirname(curr)
        return None

    def should_use_color(self, color_opt):
        if color_opt == 'always': return True
        if color_opt == 'never': return False
        return sys.stdout.isatty()

    def load_model_name(self, default_model):
        if not self.repo_root: return default_model
        config_path = os.path.join(self.repo_root, '.git', 'git-graph.toml')
        if os.path.exists(config_path):
            try:
                with open(config_path, 'r') as f:
                    for line in f:
                        if line.startswith('model ='): return line.split('"')[1]
            except: pass
        return default_model

    def get_persistence_rules(self, model_name):
        if model_name == 'git-flow': return [r'^(master|main|trunk)$', r'^(develop|dev)$', r'^feature.*$', r'^release.*$', r'^(bugfix|hotfix).*$', r'^tags/.*$']
        if model_name == 'simple': return [r'^(master|main|trunk)$']
        return []

    def get_color(self, branch_name):
        if not self.color or not branch_name: return ""
        cname = 'white'
        for rule, colors in self.terminal_colors:
            if re.match(rule, branch_name): cname = colors[0]; break
        ansi = {'bright_blue': '\033[94m', 'bright_yellow': '\033[93m', 'bright_magenta': '\033[95m', 'bright_cyan': '\033[96m', 'bright_green': '\033[92m', 'bright_red': '\033[91m', 'white': '\033[97m', 'reset': '\033[0m'}
        return ansi.get(cname, ansi['white'])

    def reset_color(self): return '\033[0m' if self.color else ""

    def get_commits(self, max_count=None):
        args = ['log', '--all', '--format=%H %P|%D|%s|%at', '--topo-order']
        if max_count: args += ['-n', str(max_count)]
        out = run_git(args, self.path)
        if not out: return []
        commits = []
        for line in out.strip().split('\n'):
            if not line: continue
            p = line.split('|')
            hp = p[0].split()
            commits.append({'hash': hp[0], 'parents': hp[1:], 'refs': p[1], 'subject': p[2], 'timestamp': int(p[3]), 'branch': None})
        return commits

    def identify_branches(self, commits):
        branches = {}
        for c in commits:
            if c['refs']:
                for r in [ref.strip() for ref in c['refs'].split(',')]:
                    name = r.split(' -> ')[1] if ' -> ' in r else r
                    if name.startswith('tag: '): name = 'tags/' + name[5:]
                    if name not in branches: branches[name] = c['hash']
        for c in commits:
            m = re.search(r"Merge (?:branch|tag) '([^']+)'", c['subject'])
            if m and m.group(1) not in branches and len(c['parents']) > 1: branches[m.group(1)] = c['parents'][1]
        return branches

    def get_persistence(self, b):
        for i, r in enumerate(self.persistence_rules):
            if re.match(r, b): return i
        return 100

    def assign_commits(self, commits, branches):
        cmap = {c['hash']: c for c in commits}
        sorted_b = sorted(branches.items(), key=lambda x: (self.get_persistence(x[0]), x[0]))
        assigned = set()
        assigns = []
        for name, head in sorted_b:
            if head not in cmap or head in assigned: continue
            curr, b_commits = head, []
            while curr in cmap and curr not in assigned:
                cmap[curr]['branch'] = name
                b_commits.append(curr); assigned.add(curr)
                if not cmap[curr]['parents']: break
                curr = cmap[curr]['parents'][0]
            if b_commits: assigns.append({'name': name, 'commits': b_commits})
        return assigns

    def order_commits(self, commits, assigns):
        counts = {c['hash']: 0 for c in commits}
        for c in commits:
            for p in c['parents']:
                if p in counts: counts[p] += 1
        cmap = {c['hash']: c for c in commits}
        bprio = {a['name']: self.get_persistence(a['name']) for a in assigns}
        def prio(h): return (bprio.get(cmap[h]['branch'], 100), cmap[h]['timestamp'])
        avail = [c['hash'] for c in commits if counts[c['hash']] == 0]
        ordered = []
        while avail:
            avail.sort(key=prio, reverse=True)
            curr = avail.pop(0); ordered.append(cmap[curr])
            for p in cmap[curr]['parents']:
                if p in counts:
                    counts[p] -= 1
                    if counts[p] == 0: avail.append(p)
        return ordered

    def assign_columns(self, ordered, assigns):
        h2i = {c['hash']: i for i, c in enumerate(ordered)}
        info = {}
        for a in assigns:
            indices = [h2i[h] for h in a['commits']]
            s, e = min(indices), max(indices)
            last = next(c for c in ordered if c['hash'] == a['commits'][-1])
            if last['parents']:
                px = h2i.get(last['parents'][0])
                if px is not None: e = max(e, px)
            info[a['name']] = (s, e)
        sorted_n = sorted([a['name'] for a in assigns], key=lambda n: (self.get_persistence(n), n))
        cols, occ = {}, []
        for n in sorted_n:
            span = set(range(info[n][0], info[n][1] + 1))
            found = False
            for i, o in enumerate(occ):
                if not (o & span): o.update(span); cols[n] = i; found = True; break
            if not found: cols[n] = len(occ); occ.append(span)
        return cols

    def render(self, ordered, cols, assigns):
        styles = {
            'normal': {'node': '●', 'merge': '○', 'v': '│', 'h': '─', 'dr': '┌', 'dl': '┐', 'ur': '└', 'ul': '┘', 'vr': '├', 'vl': '┤', 'r': '>', 'l': '<'},
            'round':  {'node': '●', 'merge': '○', 'v': '│', 'h': '─', 'dr': '╭', 'dl': '╮', 'ur': '╰', 'ul': '╯', 'vr': '├', 'vl': '┤', 'r': '>', 'l': '<'},
            'bold':   {'node': '●', 'merge': '○', 'v': '┃', 'h': '━', 'dr': '┏', 'dl': '┓', 'ur': '┗', 'ul': '┛', 'vr': '┣', 'vl': '┫', 'r': '>', 'l': '<'},
            'double': {'node': '●', 'merge': '○', 'v': '║', 'h': '═', 'dr': '╔', 'dl': '╗', 'ur': '╚', 'ul': '╝', 'vr': '╠', 'vl': '╣', 'r': '>', 'l': '<'},
            'ascii':  {'node': '*', 'merge': 'o', 'v': '|', 'h': '-', 'dr': '.', 'dl': '.', 'ur': "'", 'ul': "'", 'vr': '|', 'vl': '|', 'r': '>', 'l': '<'}
        }
        ch = styles.get(self.style, styles['normal'])
        h2i = {c['hash']: i for i, c in enumerate(ordered)}
        num_c = max(cols.values()) + 1 if cols else 0
        life = {}
        for a in assigns:
            idxs = [h2i[h] for h in a['commits']]
            s, e = min(idxs), max(idxs)
            last = next(c for c in ordered if c['hash'] == a['commits'][-1])
            if last['parents']:
                px = h2i.get(last['parents'][0])
                if px is not None: e = max(e, px)
            life[a['name']] = (s, e)

        for i, c in enumerate(ordered):
            rc = [" "] * (num_c * 2 + 1)
            cc = cols.get(c['branch'])
            for n, (s, e) in life.items():
                if s <= i <= e: rc[cols[n] * 2 + 1] = ch['v']
            if cc is not None: rc[cc * 2 + 1] = ch['merge'] if len(c['parents']) > 1 else ch['node']
            if len(c['parents']) > 1:
                for ph in c['parents'][1:]:
                    p_c = next((co for co in ordered if co['hash'] == ph), None)
                    if p_c:
                        pc = cols.get(p_c['branch'])
                        if pc is not None:
                            s_c, e_c = min(cc, pc), max(cc, pc)
                            for j in range(s_c * 2 + 2, e_c * 2 + 1): rc[j] = ch['h']
                            if pc > cc: rc[cc * 2 + 2], rc[pc * 2 + 1] = ch['l'], ch['dl']
                            else: rc[cc * 2], rc[pc * 2 + 1] = ch['r'], ch['dr']
            res = ""
            for j, char in enumerate(rc):
                if char != " ":
                    col = (j - 1) // 2
                    bn = next((n for n, c_idx in cols.items() if c_idx == col and life[n][0] <= i <= life[n][1]), None)
                    res += self.get_color(bn) + char + self.reset_color() if bn else char
                else: res += char
            ref = ""
            if c['refs']:
                bs, ts = [], []
                for r in [ref.strip() for ref in c['refs'].split(',')]:
                    if r.startswith('tag: '): ts.append(r[5:])
                    else: bs.append(r)
                p = []
                if bs: p.append("(" + ", ".join(bs) + ")")
                if ts: p.extend(["[" + t + "]" for t in ts])
                ref = " " + " ".join(p)
            print(f"{res} {c['hash'][:7]}{ref} {c['subject']}")

