    p.add_argument('sub', nargs='?', choices=['model'])
    p.add_argument('sargs', nargs='*')
    args, _ = p.parse_known_args()
    if args.version: print("git-graph 0.7.0"); sys.exit(0)
    if args.help: print("Structured Git graphs for your branching model."); sys.exit(0)
    gg = GitGraph(path=args.path, model_name=args.model, style=args.style, color='never' if args.no_color else 'auto')
    if args.sub == 'model':
        if not args.sargs: print(gg.model_name)
        elif args.sargs[0] == '--list': print("git-flow\nsimple\nnone")
        elif gg.repo_root:
            with open(os.path.join(gg.repo_root, '.git', 'git-graph.toml'), 'w') as f: f.write(f'model = "{args.sargs[0]}"\n')
            print(f"Branching model set to '{args.sargs[0]}'.")
        sys.exit(0)
    commits = gg.get_commits(max_count=args.max_count)
    if not commits: sys.exit(0)
    assigns = gg.assign_commits(commits, gg.identify_branches(commits))
    ordered = gg.order_commits(commits, assigns)
    cols = gg.assign_columns(ordered, assigns)
    gg.render(ordered, cols, assigns)
EOF
